#!/usr/bin/env bash
# Generates, or checks, onnxruntime-split-cuda12/PKGBUILD, the recipe of
# the CUDA 12 legacy line (onnxruntime-provider-cuda12-legacy), from
# onnxruntime-split/PKGBUILD.
#
#   scripts/gen-cuda12.sh            # writes onnxruntime-split-cuda12/PKGBUILD
#   scripts/gen-cuda12.sh --check    # fails, with a diff, when the
#                                    # committed one is stale
#
# The generated file is the source PKGBUILD with these lines replaced, and
# nothing else changed (the same pkgver, sources, checksums and build):
#   pkgbase=...                    pkgbase=onnxruntime-split-cuda12
#   _ortf_default_eps=...          _ortf_default_eps='cuda'
#   _ortf_default_cuda_archs=...   _ortf_default_cuda_archs=legacy
#   _ortf_default_python=...       _ortf_default_python=0
#   _ortf_line=...                 _ortf_line=cuda12
#   _ortf_cuda_major_default=...   _ortf_cuda_major_default=12
#   pkgrel=...                     pkgrel=$cuda12_pkgrel (below), with a
#                                  comment that it is this line's own
# and a comment after the Maintainer line saying it is generated. Each of
# those source lines (a whole line beginning with the name and =) must
# occur exactly once, or nothing is written: a source that no longer has
# one breaks the generator loudly instead of yielding a recipe that builds
# the main line. Writing a file already up to date leaves it untouched.
# After a change, scripts/srcinfo.sh --recipe onnxruntime-split-cuda12
# --write regenerates its .SRCINFO.
# Exit status: 0 done (or up to date), 1 stale, 2 usage error or a source
# line missing or repeated.
set -euo pipefail

prog=${0##*/}
top=$(cd "$(dirname "$0")/.." && pwd)
src=$top/onnxruntime-split/PKGBUILD
dest_dir=$top/onnxruntime-split-cuda12
dest=$dest_dir/PKGBUILD

# The cuda12 line's own pkgrel: bumped for a rebuild of this line alone
# (the main line's pkgrel is not this one's).
cuda12_pkgrel=1

usage() {
    echo "usage: $prog [--check]" >&2
    exit 2
}

mode='write'
case ${1:-} in
    '') (($# == 0)) || usage ;;
    --check) (($# == 1)) || usage; mode=check ;;
    *) usage ;;
esac

if [[ ! -f $src ]]; then
    echo "$prog: $src not found" >&2
    exit 2
fi

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

# The replacements, name -> the line(s) that replace the source's
# name=... line.
declare -A repl=(
    [pkgbase]='pkgbase=onnxruntime-split-cuda12'
    [_ortf_default_eps]="_ortf_default_eps='cuda'"
    [_ortf_default_cuda_archs]='_ortf_default_cuda_archs=legacy'
    [_ortf_default_python]='_ortf_default_python=0'
    [_ortf_line]='_ortf_line=cuda12'
    [_ortf_cuda_major_default]='_ortf_cuda_major_default=12'
    [pkgrel]="# onnxruntime-split-cuda12's own pkgrel (scripts/gen-cuda12.sh); the
# notes above are those of onnxruntime-split's.
pkgrel=$cuda12_pkgrel"
)
banner="# Generated by scripts/gen-cuda12.sh from onnxruntime-split/PKGBUILD
# (https://github.com/rsd/omarchy-onnxruntime): do not edit; change the
# source and regenerate."

# generate <file>: writes the generated PKGBUILD to <file>.
generate() {
    local line name bad=0 maint=0
    local -A seen=()
    local -a out=()
    while IFS= read -r line || [[ -n $line ]]; do
        name=''
        [[ ! $line =~ ^([A-Za-z_][A-Za-z0-9_]*)= ]] || name=${BASH_REMATCH[1]}
        if [[ -n $name && -n ${repl[$name]+x} ]]; then
            seen[$name]=$((${seen[$name]:-0} + 1))
            out+=("${repl[$name]}")
        else
            out+=("$line")
        fi
        if [[ $line == '# Maintainer: '* ]]; then
            maint=$((maint + 1))
            out+=('#' "$banner")
        fi
    done <"$src"
    for name in "${!repl[@]}"; do
        if [[ ${seen[$name]:-0} != 1 ]]; then
            echo "$prog: $src has ${seen[$name]:-0} lines $name=..., not exactly one" >&2
            bad=1
        fi
    done
    if ((maint != 1)); then
        echo "$prog: $src has $maint '# Maintainer: ' lines, not exactly one" >&2
        bad=1
    fi
    ((bad == 0)) || return 2
    printf '%s\n' "${out[@]}" >"$1"
}

generate "$tmp/PKGBUILD" || exit

case $mode in
    write)
        if [[ -f $dest ]] && cmp -s -- "$tmp/PKGBUILD" "$dest"; then
            echo "onnxruntime-split-cuda12/PKGBUILD is up to date"
        else
            mkdir -p -- "$dest_dir"
            cp -- "$tmp/PKGBUILD" "$dest.tmp"
            mv -f -- "$dest.tmp" "$dest"
            echo "wrote $dest; then run scripts/srcinfo.sh --recipe onnxruntime-split-cuda12 --write"
        fi
        ;;
    check)
        if [[ ! -f $dest ]]; then
            echo "$prog: $dest does not exist: run $prog" >&2
            exit 1
        fi
        if ! diff -u --label "committed onnxruntime-split-cuda12/PKGBUILD" --label "generated" \
            "$dest" "$tmp/PKGBUILD"; then
            echo "$prog: onnxruntime-split-cuda12/PKGBUILD is stale: run $prog" >&2
            exit 1
        fi
        echo "onnxruntime-split-cuda12/PKGBUILD is up to date"
        ;;
esac
